import { useState, useEffect } from "react"
import Home from "../defaultresort/home";
import "../defaultresort/roomcarts.css"

const AllRoomsList = () => {

    let [ store, setStore ] = useState([]);

    const getdata = () => {
        try{
            fetch("http://localhost:1234/room")
            .then( res => res.json() )
            .then( info => {
                setStore(info)
            })
        }catch(error){
            console.error(" Data fetching is not processed ")
        }
    }

    useEffect( () => {
        getdata()
    }, [])

    return(
        <>
            <Home />

        </>
    )
}

export default AllRoomsList
